import { Children, type ReactNode } from "react";
import { cn } from "@/lib/cn";

// KMP-C7 (specs/KMP-C7-grouped-list-card.md). A card holding a real list of rows (KMP-C8, supplied by the consumer).
// The heading and the sentence explaining a name-only group live outside the card. Never clips overflow (focus rings).

export type GroupedListCardProps = {
  /** "name-only" is told apart by sunken fill and a solid edge, never a dashed one (dashed means draft week). */
  variant?: "plain" | "name-only";
  children: ReactNode;
  className?: string;
};

export function GroupedListCard({ variant = "plain", children, className }: GroupedListCardProps) {
  const rows = Children.toArray(children).filter(Boolean);
  if (rows.length === 0) return null; // no empty shell
  return (
    <ul
      role="list"
      className={cn(
        "rounded-card border-bw-default",
        variant === "plain" ? "border-border-card bg-surface-raised" : "border-border bg-surface-sunken",
        "[&>li+li]:border-t-bw-default [&>li+li]:border-border-subtle",
        "[&>li:first-child]:rounded-t-card-inner [&>li:last-child]:rounded-b-card-inner",
        className,
      )}
    >
      {rows.map((r, i) => (
        <li key={i}>{r}</li>
      ))}
    </ul>
  );
}
